pub trait LegacyKeyHandler {
    /// Explicitly opt in to authenticated migration of a legacy keyblob which
    /// still parses as the current format. Only a SOFTWARE TA consults this
    /// hook. Hardware implementations retain their existing behavior.
    ///
    /// Return true only after authenticating the original blob, hidden
    /// parameters and root of trust. Unsupported or invalid legacy profiles
    /// must return an error, not fall back to current-format processing.
    /// The normal upgrade operation then converts and re-encrypts the key.
    fn software_keyblob_upgrade_required(
        &self,
        _keyblob: &[u8],
        _params: &[KeyParam],
        _root_of_trust: &BootInfo,
    ) -> Result<bool, Error> {
        Ok(false)
    }

// The historical in-process nonsecure provider used this same wire
// format with a TrustedEnvironment characteristic. Recognize it only
// through an explicitly opted-in software handler, which authenticates
// the original encrypted blob before asking the caller to upgrade.
if self.hw_info.security_level == SecurityLevel::Software {
    if let Some(old_key) = self.dev.legacy_key.as_ref() {
        if old_key.software_keyblob_upgrade_required(
            key_blob, params, self.boot_info()?,
        )? {
            return Err(km_err!(
                KeyRequiresUpgrade,
                "authenticated legacy software key requires upgrade"
            ));
        }
    }
}
let encrypted_keyblob = match keyblob::EncryptedKeyBlob::new(key_blob) {

// Only this in-process software provider migrates its authenticated
// historical KMR V1 blobs; the generic TA hook remains disabled.
legacy_key: Some(Box::new(legacy_nonsecure::LegacyNonsecureKmr::new())),

    KeyMintTa::new(hw_info, RpcInfo::V3(rpc_info_v3), boringssl_crypto_impls(), dev)
}

